@CrossOrigin
@RestController
@RequestMapping("/PolicyQuery")
public class PolicyQueryRestController extends BaseSpringRestController {
	
	public PolicyQueryRestController( PolicyService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Policy using a UUID
     * @param		UUID policyId
     * @return		Policy
     */    
    @GetMapping("/load")
    public Policy load( @RequestParam(required=true) UUID policyId ) {
    	Policy entity = null;

    	try {  
    		entity = service.getPolicy( new PolicyFetchOneSummary( policyId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Policy using Id " + policyId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Policy business objects
     * @return		Set<Policy>
     */
    @GetMapping("/")
    public List<Policy> loadAll() {                
    	List<Policy> policyList = null;
        
    	try {
            // load the Policy
            policyList = service.getAllPolicy();
            
            if ( policyList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Policys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Policys ", exc );
        	return null;
        }

        return policyList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Policy policy = null;
    protected PolicyService service = null;
    private static final Logger LOGGER = Logger.getLogger(PolicyQueryRestController.class.getName());
    
}
